const sample=[
['Science','What is the chemical symbol for gold?'],['Maths','What is 12 × 12?'],['Logic','If all Bloops are Razzies and all Razzies are Lazzies, are all Bloops Lazzies?'],['Geography','What is the longest river in South America?'],['History','Which wall fell in 1989?'],['Technology','What does CPU stand for?'],['General knowledge','How many sides does a hexagon have?'],['Pop culture','Which fictional wizard has a lightning-shaped scar?'],['Sports','How many players does a soccer team have on the pitch?'],['Riddle','What has keys but cannot open locks?']
];
const defaults={teamA:'Team Red',teamB:'Team Blue',size:4,line:4,duration:30,startingTeam:0,gameReady:false,selectionVersion:1,questions:sample.map(([,text])=>({text})),claims:[],attempts:[],turn:0,selected:null,seconds:30,started:false,finished:false};
let state=structuredClone(defaults),interval,saveHandle,activeRound=0,stageStarted=false,imageHidden=false;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const FIREBASE_STATE_URL='https://lsc-trivia-bingo-default-rtdb.asia-southeast1.firebasedatabase.app/triviaBingo/current.json';
function database(){return new Promise((resolve,reject)=>{let request=indexedDB.open('TriviaGridDatabase',1);request.onupgradeneeded=()=>request.result.createObjectStore('games');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
function fixedTeams(snapshot){return {...snapshot,teamA:'Team Red',teamB:'Team Blue'}}
async function loadLocal(){try{let db=await database();return fixedTeams({...defaults,...(await new Promise((resolve,reject)=>{let request=db.transaction('games').objectStore('games').get('current');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)}))})}catch{return structuredClone(defaults)}}
async function load(){try{let response=await fetch(FIREBASE_STATE_URL,{cache:'no-store'});if(!response.ok)throw new Error();let remote=await response.json();if(remote)return fixedTeams({...defaults,...remote})}catch{}return loadLocal()}
function saveLocal(snapshot){database().then(db=>{let tx=db.transaction('games','readwrite');tx.objectStore('games').put(snapshot,'current')}).catch(()=>{})}
function save(){clearTimeout(saveHandle);let snapshot=structuredClone(state);saveHandle=setTimeout(async()=>{try{let response=await fetch(FIREBASE_STATE_URL,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(snapshot)});if(!response.ok)throw new Error()}catch{saveLocal(snapshot)}},300)}
async function loadSharedQuestions(){try{let response=await fetch('./questions.json',{cache:'no-store'});if(!response.ok)throw new Error();let questions=await response.json();return questions.filter(q=>typeof q.text==='string'&&q.text.trim()).map(q=>({text:q.text.trim(),sourceNumber:q.sourceNumber??null,instructions:q.instructions??'',type:q.type??'',images:Array.isArray(q.images)?q.images:[],answer:q.answer??'',visualOnly:q.visualOnly===true}))}catch{return sample.map(([,text])=>({text}))}}
async function hydrateQuestionMetadata(questions){try{let catalogue=await loadSharedQuestions();return questions.map(q=>{let match=catalogue.find(item=>item.sourceNumber!==null&&item.sourceNumber===q.sourceNumber)||catalogue.find(item=>item.text===q.text);return match?{...q,...match}:q})}catch{return questions}}
function questionType(q){if(q.type)return q.type;let n=Number(q.sourceNumber);if([33,29,71,31,54,30,56].includes(n))return 'teamChallenge';if(n===59)return 'relay5';if([45,46,49,58].includes(n))return 'relay8';if(n===50)return 'preview';return 'immediate'}
function typeLabel(q){return {immediate:'Knowledge',preview:'Picture / question preview',relay3:'Relay of 3',relay5:'Relay of 5',relay8:'Relay of 8',teamChallenge:'Team Challenge'}[questionType(q)]||'Knowledge'}
function categoryFor(q){if(q.category)return q.category;if(q.type==='teamChallenge')return 'Team Challenge';if(q.type==='relay3'||q.type==='relay5'||q.type==='relay8')return 'Relay';if(q.type==='preview')return 'Picture Challenge';if(q.type==='immediate')return 'Knowledge';let n=Number(q.sourceNumber),text=(q.text||'').toLowerCase();if([33,29,71,31,54,30,56].includes(n))return 'Team Challenge';if(n===46)return 'Memory Challenge';if(n===45||n===49)return 'Relay';if(n===58)return 'Picture Challenge';if(n===59)return 'Team Puzzle';if(n===50||n===55)return 'Number Puzzle';if(n===43)return 'Logic Puzzle';if(n===31)return 'Team Challenge';if(n===25||n===26)return 'Picture Knowledge';if(/riddle|what has|what comes|the more you take/.test(text))return 'Riddle';return 'Knowledge'}
function questionSeconds(q){return Math.max(5,Math.min(300,Number(q.timeLimit)||state.duration))}
function boardQuestions(){return state.questions.filter(q=>q.included!==false).slice(0,state.size**2)}
function ensureQuestions(){const needed=state.size**2;while(state.questions.length<needed)state.questions.push({text:'Add your question in Question studio.',included:true,type:'immediate'});state.claims=Array.from({length:needed},(_,i)=>state.claims[i]??null);state.attempts=Array.from({length:needed},(_,i)=>state.attempts?.[i]??null)}
function teamName(team=state.turn){return team===0?state.teamA:state.teamB}function turnText(team=state.turn){return teamName(team)}function score(t){return state.claims.filter(x=>x===t).length}
function setView(view){$$('.view').forEach(v=>v.classList.toggle('active',v.id===view));$$('.nav-link').forEach(b=>b.classList.toggle('active',b.dataset.view===view));render()}
function tile(i,readOnly=false){let c=state.claims[i],attempt=state.attempts[i],b=document.createElement('button');b.className=`tile ${c!==null?`claim-${c===0?'a':'b'}`:attempt!==null?`tried-${attempt===0?'a':'b'}`:''}`;b.disabled=readOnly||c!==null||state.finished;b.innerHTML=`<span class="tile-number">${String(i+1).padStart(2,'0')}</span>`;if(!readOnly)b.onclick=()=>openQuestion(i);return b}
function render(){ensureQuestions();save();$('#setup-stage').classList.toggle('open',!state.gameReady);$('#team-a-name').textContent=state.teamA;$('#team-b-name').textContent=state.teamB;$('#turn-label').textContent=state.finished?'Match complete':turnText();$('#timer').textContent=state.seconds;$('#timer').className=`timer ${state.started?'running':''} ${state.seconds<=10&&state.started?'urgent':''}`;$('#game-status').textContent=state.finished?'Start a new game to play again.':state.started?`${teamName()} has ${state.seconds} seconds to answer.`:'Choose an unclaimed tile to open its instructions.';let grid=$('#grid');grid.style.setProperty('--size',state.size);grid.replaceChildren(...boardQuestions().map((_,i)=>tile(i)));renderPlayers();renderSettings()}
function renderPlayers(){let view=$('#players'),isPlayerView=view.classList.contains('active'),root=document.documentElement;view.classList.toggle('team-a-turn',state.turn===0);view.classList.toggle('team-b-turn',state.turn===1);for(let node of [document.body,root]){node.classList.toggle('player-mode',isPlayerView);node.classList.toggle('player-team-a',state.turn===0);node.classList.toggle('player-team-b',state.turn===1)}let grid=$('#player-grid'),timer=$('#player-timer');grid.style.setProperty('--size',state.size);grid.replaceChildren(...boardQuestions().map((q,i)=>tile(i)));$('#player-turn').textContent=state.finished?'Match complete':turnText();timer.textContent=state.seconds;timer.style.setProperty('display',state.selected===null||!stageStarted?'none':'grid','important');$('#player-a').textContent=`${state.teamA} · ${score(0)}`;$('#player-b').textContent=`${state.teamB} · ${score(1)}`}
const builtInImages={25:['data:image/jpeg;base64,'],43:['data:image/jpeg;base64,'],26:['question-images/enigma.jpg'],41:['question-images/hard-square-grid.svg'],46:['question-images/memory-scene.svg'],55:['question-images/tile-09-number-sequence.png'],50:['question-images/tile-14-one-number-puzzle.svg?v=3']};
function imagesFor(q){let n=Number(q.sourceNumber),saved=Array.isArray(q.images)?q.images:(q.image?[q.image]:[]),built=builtInImages[n]||[];let forced=n===25||n===43||n===50||n===55||/four-digit passcode|letter replaces the question mark/i.test(q.text||'')||String(q.answer||'').trim().toUpperCase().startsWith('ROSE');return forced&&built.length?built:(saved.length?saved:built)}
function plannedRounds(q){let type=questionType(q);if(type==='relay3')return 3;if(type==='relay5')return 5;if(type==='relay8')return 8;if(imagesFor(q).length)return imagesFor(q).length;if(q.sourceNumber===59||/anagram/i.test(q.text))return 5;return [45,49,50,58].includes(q.sourceNumber)?8:1}
function isNormalTrivia(q){return false}
function autoInstructions(q){let n=q.sourceNumber,text=q.text.toLowerCase();if([45,46,49,50,58].includes(n)||text.includes('logo')||text.includes('landmark')||text.includes('silhouette')||text.includes('picture'))return 'Add one image per round in Question studio. Press Start, show each round with Next/Previous, then judge the team’s final result.';if(n===59||text.includes('anagram'))return 'Press Start. Work together on one anagram at a time. Use Next only after agreeing the answer; claim the square only if all three are solved.';if(text.includes('relay')||text.includes('each player'))return 'Every team member must take part. Read the prompt, press Start when ready, then judge the completed challenge.';return 'Read the question, allow discussion, then press Correct or Incorrect after the team gives its final answer.'}
function challengeName(q){let n=q.sourceNumber,text=q.text.toLowerCase();if(n===45||text.includes('logo'))return 'Logo relay';if(n===46||text.includes('memory'))return 'Memory challenge';if(n===49||text.includes('landmark'))return 'Landmark challenge';if(n===50||text.includes('picture'))return 'Picture challenge';if(n===58||text.includes('silhouette'))return 'Picture guessing challenge';if(n===59||text.includes('anagram'))return 'Team anagram challenge';if(text.includes('riddle'))return 'Riddle';return 'Trivia challenge'}
function renderSettings(){if(!$('#settings').classList.contains('active'))return;$('#win-condition').value=String(state.line);let selected=boardQuestions(),editor=$('#question-editor');$('#question-count').textContent=`${selected.length} active board questions`;editor.replaceChildren(...selected.map((q,boardTile)=>{let i=state.questions.indexOf(q),images=imagesFor(q),d=document.createElement('article'),type=questionType(q);d.className='question-card';d.innerHTML=`<header>QUESTION ${String(boardTile+1).padStart(2,'0')} · TILE ${String(boardTile+1).padStart(2,'0')} · ${esc(categoryFor(q))}</header><label><strong>Question type</strong> <select data-key="type"><option value="immediate" ${type==='immediate'?'selected':''}>Knowledge</option><option value="preview" ${type==='preview'?'selected':''}>Picture / question preview</option><option value="relay3" ${type==='relay3'?'selected':''}>Relay of 3</option><option value="relay5" ${type==='relay5'?'selected':''}>Relay of 5</option><option value="relay8" ${type==='relay8'?'selected':''}>Relay of 8</option><option value="teamChallenge" ${type==='teamChallenge'?'selected':''}>Team Challenge</option></select></label><label><strong>Time for this question (seconds)</strong> <input data-key="timeLimit" type="number" min="5" max="300" step="5" value="${questionSeconds(q)}"></label><label>Question<textarea data-key="text" maxlength="300">${esc(q.text)}</textarea></label><label>Add round images <input class="image-input" type="file" accept="image/*" multiple></label><p class="note">Type and time limit are only shown in Question Studio. Each attached image becomes a numbered round with Previous and Next controls.</p><div class="image-previews">${images.map((src,n)=>`<figure><img src="${src}" alt="Round ${n+1}"><button class="remove-image" data-image="${n}" type="button" aria-label="Remove round ${n+1}">×</button></figure>`).join('')}</div>`;d.querySelectorAll('[data-key]').forEach(input=>{let update=e=>{state.questions[i][e.target.dataset.key]=e.target.dataset.key==='timeLimit'?Math.max(5,Math.min(300,Number(e.target.value)||state.duration)):e.target.value;save()};input.oninput=update;input.onchange=update});d.querySelector('.image-input').onchange=e=>{let files=[...e.target.files];if(!files.length)return;Promise.all(files.map(file=>new Promise(resolve=>{let reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.readAsDataURL(file)}))).then(newImages=>{state.questions[i].images=[...imagesFor(state.questions[i]),...newImages];delete state.questions[i].image;save();renderSettings()})};d.querySelectorAll('.remove-image').forEach(button=>button.onclick=()=>{state.questions[i].images=imagesFor(state.questions[i]);state.questions[i].images.splice(+button.dataset.image,1);delete state.questions[i].image;if(!state.questions[i].images.length)delete state.questions[i].images;save();renderSettings()});return d}))}
function esc(v=''){return String(v).replaceAll('&','&amp;').replaceAll('"','&quot;').replaceAll('<','&lt;')}
function closeStage(){$('#question-stage').classList.remove('open');stageStarted=false}
function renderQuestionText(q,media){let [question,...rest]=q.text.split('\n'),choiceText=rest.join(' ').trim();$('#stage-title').textContent=question;let options=choiceText.match(/[A-D]\.\s*.*?(?=\s+[A-D]\.\s*|$)/g);if(options?.length){let list=document.createElement('div');list.className='stage-options';options.forEach(choice=>{let row=document.createElement('div');row.className='stage-option';row.textContent=choice.trim();list.append(row)});media.append(list)}else if(rest.length){let extra=document.createElement('p');extra.className='stage-options';extra.textContent=rest.join('\n');media.append(extra)}}
function isRiddle(q){return categoryFor(q)==='Riddle'}
function isImmediateResponse(q){let category=categoryFor(q);return questionType(q)==='immediate'&&!isRiddle(q)&&!['Relay','Team Puzzle','Team Challenge','Memory Challenge','Picture Challenge'].includes(category)}
function introInstructions(q){return String(q.instructions||'').trim()||autoInstructions(q)}
function playerCategory(q){if(isImmediateResponse(q))return 'Immediate response';return categoryFor(q)==='Relay'?'Team Relay':categoryFor(q)}
function renderStage(){let q=boardQuestions()[state.selected];if(!q)return;let images=imagesFor(q),rounds=plannedRounds(q),hasMultiple=rounds>1,riddle=isRiddle(q);$('#question-stage').classList.toggle('with-picture',stageStarted&&images.length>0);$('#question-stage').classList.toggle('landmark-round',stageStarted&&Number(q.sourceNumber)===49);$('#question-stage').classList.toggle('riddle-intro',!stageStarted&&riddle);$('#stage-kind').textContent=playerCategory(q);$('#stage-progress').textContent=stageStarted?(hasMultiple?`Round ${activeRound+1} of ${rounds}`:''):riddle?'Ready':'Instructions';$('#stage-hide-image').hidden=!stageStarted||!images.length;$('#stage-hide-image').textContent=imageHidden?'Show picture':'Hide picture';$('#stage-start').hidden=stageStarted;$('#stage-navigation').hidden=!stageStarted||!hasMultiple;$('#stage-judge').hidden=!stageStarted;$('#stage-timer').hidden=!stageStarted;$('#stage-previous').disabled=activeRound===0;$('#stage-next').disabled=activeRound===rounds-1;let media=$('#stage-media');media.replaceChildren();if(!stageStarted){if(riddle){$('#stage-title').textContent=''}else if([25,55,43,50].includes(Number(q.sourceNumber))){$('#stage-title').textContent=introInstructions(q)}else if(isImmediateResponse(q)){$('#stage-title').textContent='Answer the question.'}else{renderQuestionText(q,media)}return}if(images[activeRound]){$('#stage-title').textContent=hasMultiple?`${challengeName(q)} — round ${activeRound+1}`:challengeName(q);if(imageHidden){let hidden=document.createElement('p');hidden.className='stage-ready';hidden.textContent='Picture hidden';media.append(hidden)}else{if(!hasMultiple&&!q.visualOnly)renderQuestionText(q,media);let image=document.createElement('img');image.src=images[activeRound];image.alt=`Challenge round ${activeRound+1}`;media.append(image)}}else if(q.sourceNumber===59||/anagram/i.test(q.text)){let anagrams=['LISTEN','EARTH','ELBOW','DUSTY','GLEAN'];$('#stage-title').textContent=`Anagram ${activeRound+1} of 5`;let prompt=document.createElement('p');prompt.className='stage-prompt';prompt.textContent=anagrams[activeRound];media.append(prompt)}else if(hasMultiple){renderQuestionText(q,media);let prompt=document.createElement('p');prompt.className='stage-prompt';prompt.textContent=`Round ${activeRound+1} of ${rounds}. Take this round’s answer, then use Next when ready.`;media.append(prompt)}else{renderQuestionText(q,media)}}
function beginTimer(){state.started=true;let deadline=Date.now()+state.seconds*1000;clearInterval(interval);interval=setInterval(()=>tick(deadline),200)}
function openQuestion(i){stopTimer();state.selected=i;let q=boardQuestions()[i];state.seconds=questionSeconds(q);$('#stage-timer').textContent=state.seconds;$('#player-timer').textContent=state.seconds;state.started=false;activeRound=0;imageHidden=false;stageStarted=isNormalTrivia(q);$('#question-stage').classList.add('open');if(stageStarted)beginTimer();renderStage();render()}
function startChallenge(){if(state.selected===null)return;stageStarted=true;imageHidden=false;state.seconds=questionSeconds(boardQuestions()[state.selected]);beginTimer();renderStage();render()}
function moveRound(change){let q=boardQuestions()[state.selected],last=plannedRounds(q)-1;activeRound=Math.max(0,Math.min(last,activeRound+change));imageHidden=false;renderStage()}
function sayCountdown(number){if(number>5||number<1||!('speechSynthesis'in window))return;window.speechSynthesis.cancel();window.speechSynthesis.speak(new SpeechSynthesisUtterance(String(number)))}
function tick(deadline){if(!state.started)return;let prior=state.seconds;state.seconds=Math.max(0,Math.ceil((deadline-Date.now())/1000));$('#stage-timer').textContent=state.seconds;$('#player-timer').textContent=state.seconds;if(state.seconds<=0){stopTimer();closeStage();state.selected=null;switchTurn('Time is up — square stays open.');return}if(state.seconds!==prior){sayCountdown(state.seconds);render()}}
function stopTimer(){clearInterval(interval);window.speechSynthesis?.cancel();state.started=false}
function switchTurn(message){state.turn=state.turn?0:1;state.seconds=state.duration;state.selected=null;save();render();if(message)$('#game-status').textContent=message}
function hasLine(player){let n=state.size,k=Math.min(state.line,n),a=state.claims;for(let r=0;r<n;r++)for(let c=0;c<n;c++)for(const[dr,dc]of[[0,1],[1,0],[1,1],[1,-1]]){let endR=r+(k-1)*dr,endC=c+(k-1)*dc;if(endR>=0&&endR<n&&endC>=0&&endC<n&&Array.from({length:k},(_,z)=>a[(r+z*dr)*n+c+z*dc]===player).every(Boolean))return true}return false}
function declareWinner(winner,reason){stopTimer();state.finished=true;save();$('#winner-title').textContent=winner===null?'It’s a tie!':`${teamName(winner)} wins!`;$('#winner-copy').textContent=reason;$('#winner-modal').showModal();render()}
function resetGame(){stopTimer();state={...state,claims:Array(state.size**2).fill(null),attempts:Array(state.size**2).fill(null),turn:state.startingTeam,selected:null,seconds:state.duration,started:false,finished:false};save();render()}
function leaveFullscreen(){if(document.fullscreenElement)document.exitFullscreen().catch(()=>{})}
function showStartSetup(){leaveFullscreen();stopTimer();state={...state,gameReady:false,selected:null,seconds:state.duration,started:false,finished:false};$('#setup-intro').classList.remove('hidden');$('#quick-setup').classList.add('hidden');save();render()}
$('.topbar nav').onclick=e=>{if(e.target.dataset.view)setView(e.target.dataset.view)};$('.brand').onclick=e=>{if(e.currentTarget.dataset?.view)setView(e.currentTarget.dataset.view)};$('#win-condition').onchange=e=>{state.line=Number(e.target.value)===3?3:4;save();render()};$('#new-game').onclick=showStartSetup;$('#start-timer').onclick=()=>{if(state.selected===null){$('#game-status').textContent='Select a tile first.';return}startChallenge()};$('#end-game').onclick=()=>{let a=score(0),b=score(1);declareWinner(a===b?null:a>b?0:1,`Final score: ${state.teamA} ${a} — ${b} ${state.teamB}.`)};
$('#stage-close').onclick=()=>{closeStage();stopTimer();state.selected=null;render()};$('#stage-start').onclick=startChallenge;$('#stage-hide-image').onclick=()=>{imageHidden=!imageHidden;renderStage()};$('#stage-previous').onclick=()=>moveRound(-1);$('#stage-next').onclick=()=>moveRound(1);$('#stage-incorrect').onclick=()=>{let p=state.turn;if(state.selected===null)return;state.attempts[state.selected]=p;closeStage();stopTimer();switchTurn('Unsuccessful attempt — the tile is marked and remains available.')};$('#stage-correct').onclick=()=>{let p=state.turn;if(state.selected===null)return;state.claims[state.selected]=p;closeStage();stopTimer();if(hasLine(p))declareWinner(p,`${teamName(p)} connected ${state.line} squares in a row.`);else switchTurn('Correct — square claimed!')};$('#winner-new-game').onclick=()=>{$('#winner-modal').close();resetGame()};
$('#setup-begin').onclick=()=>{leaveFullscreen();$('#setup-intro').classList.add('hidden');$('#quick-setup').classList.remove('hidden');$('#setup-starting-team').value=state.startingTeam};$('#quick-setup').onsubmit=e=>{e.preventDefault();leaveFullscreen();state.startingTeam=+$('#setup-starting-team').value;state.gameReady=true;resetGame()};
document.exitFullscreen?.().catch(()=>{});
(async()=>{state={...(await load()),gameReady:true};state.size=4;state.line=4;let catalogue=await loadSharedQuestions();if(state.catalogueVersion!==3&&catalogue.length>=25){state.questions=catalogue.map((q,i)=>({...q,included:i<16}));state.catalogueVersion=3;state.selectionVersion=2}state.questions=await hydrateQuestionMetadata(state.questions);state.questions=state.questions.map(q=>Number(q.sourceNumber)===59?{...q,type:'relay5'}:[33,29,71,31,54,30,56].includes(Number(q.sourceNumber))?{...q,type:'teamChallenge'}:q);ensureQuestions();save();render()})();
